```javascript
function solve(input) {
  const byEvent = new Map();
  for (const record of input) {
    if (!byEvent.has(record.eventId)) {
      byEvent.set(record.eventId, record);
    }
  }
  const balances = new Map();
  for (const record of byEvent.values()) {
    balances.set(record.account, (balances.get(record.account) ?? 0) + record.delta);
  }
  return [...balances.entries()].sort((a, b) =>
    a[0] < b[0] ? -1 : a[0] > b[0] ? 1 : 0
  );
}
```

