    const u = edge[0];
    const v = edge[1];
    if (u === v) return null;
    if (!nodeSet.has(u) || !nodeSet.has(v)) continue;
    const neighbors = adj.get(u);
    if (neighbors.has(v)) continue;
    neighbors.add(v);
    inDegree.set(v, inDegree.get(v) + 1);
