```javascript
function solve(input) {
  if (!input) return [];
  const rows = [];
  let row = [];
  let field = '';
  let inQuotes = false;
  let rowStarted = false;
  let i = 0;
  const len = input.length;

  while (i < len) {
    const c = input[i];

    if (inQuotes) {
      if (c === '"') {
        if (input[i + 1] === '"') {
          field += '"';
          i += 2;
        } else {
          inQuotes = false;
          i++;
        }
      } else {
        field += c;
        i++;
      }
      continue;
    }

    if (c === '"') {
      inQuotes = true;
      rowStarted = true;
      i++;
    } else if (c === ',') {
      row.push(field);
      field = '';
      rowStarted = true;
      i++;
    } else if (c === '\r') {
      if (input[i + 1] === '\n') i += 2;
      else i++;
      row.push(field);
      rows.push(row);
      row = [];
      field = '';
      rowStarted = false;
    } else if (c === '\n') {
      row.push(field);
      rows.push(row);
      row = [];
      field = '';
      rowStarted = false;
      i++;
    } else {
      field += c;
      rowStarted = true;
      i++;
    }
  }

  if (rowStarted) {
    row.push(field);
    rows.push(row);
  }

  return rows;
}
```

